package com.android.tools.lint.checks;

import static com.android.SdkConstants.*;
import static com.android.resources.ResourceUrl.*;

import com.android.annotations.NonNull;
import com.android.annotations.Nullable;
import com.android.ide.common.resources.AbstractResourceRepository;
import com.android.ide.common.resources.ResourceItem;
import com.android.ide.common.resources.ResourceRepository;
import com.android.ide.common.resources.configuration.FolderConfiguration;
import com.android.resources.ResourceUrl;
import com.android.resources.ResourceType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.android.tools.lint.detector.api.XmlScanner;
import com.android.tools.lint.detector.api.XmlScannerConstants;
import java.util.Collection;
import java.util.List;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

public class ManifestResourceDetector extends Detector implements Detector.XmlScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            ManifestResourceDetector.class,
            Scope.MANIFEST_SCOPE
    );

    public static final Issue ISSUE = Issue.create(
            "ManifestResource",
            "Manifest resource references cannot vary across configurations",
            "Resources referenced from the manifest cannot vary across configurations, "
                    + "except by version, and except for the application label and icon. "
                    + "Other configuration-specific variations will not be reliably resolved.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            IMPLEMENTATION
    );

    @Override
    @Nullable
    public Collection<String> getApplicableAttributes() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        Element element = attribute.getOwnerElement();
        if (element == null) return;
        String value = attribute.getValue();
        if (value == null || value.isEmpty()) return;

        ResourceUrl url = ResourceUrl.parse(value);
        if (url == null || url.isTheme() || url.type == null || url.name == null) {
            return;
        }

        if (url.isFramework()) {
            return;
        }

        if (isExempt(element, attribute)) {
            return;
        }

        AbstractResourceRepository repository = context.getProject().getAaptAwareResourceRepository();
        if (repository == null) return;

        List<ResourceItem> items = repository.getResourceItem(url.type, url.name);
        if (items == null || items.size() <= 1) {
            return;
        }

        if (isVersionOnlyVariation(items)) {
            return;
        }

        context.report(ISSUE, attribute, context.getValueLocation(attribute),
                "This resource reference (" + url.toString() + ") has configuration variants; "
                        + "resources in the manifest should not vary across configurations");
    }

    private boolean isExempt(Element element, Attr attribute) {
        String attrName = attribute.getLocalName();
        if (attrName == null) return false;
        String tag = element.getTagName();
        if (TAG_APPLICATION.equals(tag) && (ATTR_ICON.equals(attrName) || ATTR_LABEL.equals(attrName))) {
            return true;
        }
        return false;
    }

    private boolean isVersionOnlyVariation(List<ResourceItem> items) {
        for (ResourceItem item : items) {
            String qualifiers = item.getQualifiers();
            if (qualifiers == null || qualifiers.isEmpty()) continue;
            FolderConfiguration config = FolderConfiguration.getConfig(qualifiers);
            if (config == null) continue;
            if (config.getQualifierCount() != 1 || config.getVersionQualifier() == null) {
                return false;
            }
        }
        return true;
    }
}
```

