        ResourceUrl url = ResourceUrl.parse(value);
        if (url == null || url.isCreate() || url.isTheme()) {
            return;
        }

        ResourceReference reference = new ResourceReference(url);
        if (reference == null) {
            return;
        }

        String tag = attribute.getOwnerElement().getLocalName();
        String name = attribute.getLocalName();
        if (TAG_APPLICATION.equals(tag) && (ATTR_LABEL.equals(name) || ATTR_ICON.equals(name))) {
            return;
        }
        if (TAG_MANIFEST.equals(tag) && ATTR_VERSION_NAME.equals(name)) {
            return;
