        if (hasAlternates(context, reference)) {
            String message = String.format(
                    "The attribute %1$s in the manifest cannot reference a resource that varies "
                            + "across configurations (except as a special case, by version, and "
                            + "except for the application title and icon)",
                    attribute.getName());
            context.report(ISSUE, attribute, context.getValueLocation(attribute), message);
        }
    }

    private boolean hasAlternates(@NonNull XmlContext context, @NonNull ResourceReference reference) {
        LintClient client = context.getClient();
        Project project = context.getMainProject();
        List<ResourceItem> resources = reference.getResources(client, project);
        if (resources == null || resources.size() <= 1) {
            return false;
        }

        for (ResourceItem resource : resources) {
            File file = resource.getFile();
            if (file == null) {
                continue;
            }
            File parent = file.getParentFile();
            if (parent == null) {
                continue;
